// Тикет #6a86f7d99a8f «עיצוב מוקאפ: תהילים — רשימת פרקים וקטעים», проверен 07.10.2026 → עבר QA (session.json: «переключатель פרקי אבות сделан»).
// Опора: реджект 27.09 п.1 (переключатель «תהילים / פרקי אבות» вверху, в «פרקי אבות» — список); S-24 AC5 (узнаваемое имя פריט).
// Скрин d99a8f-2-avot-tab: пояснение «פרקי אבות נאמרים בשבתות שאחרי פסח, פרק אחד בכל שבת, במחזור של שישה פרקים.»,
// 6 פרקים א׳–ו׳ («משה קבל תורה», «רבי אומר, איזוהי», «עקביא בן מהללאל», «בן זומא אומר,», «בעשרה מאמרות נברא», «שנו חכמים בלשון»), чипов дней нет.
// «פרק השבוע» из реджекта — нет в документации и не реализовано (вердикт 07.10) — не проверяем.
import { expect } from '@wdio/globals';
import { byText, byTextContains, expectVisibleText, expectTextContains } from '../../helpers/ui.ts';
import { goTab } from '../../helpers/nav.ts';
import { toHome } from '../../helpers/app.ts';
import { searchField, shown, tapTextInMiddle } from '../_lib/app-0710.ts';

const AVOT_ROWS = ['משה קבל תורה', 'רבי אומר', 'עקביא בן מהללאל', 'בן זומא אומר', 'בעשרה מאמרות נברא', 'שנו חכמים בלשון'];

describe('Список תהילים: вкладка פרקי אבות', () => {
  afterEach(async () => {
    // Вернуть переключатель на «תהילים», если тест остановился во вкладке «פרקי אבות».
    if (await shown(byTextContains('פרקי אבות נאמרים'))) await tapTextInMiddle('תהילים');
    await toHome();
  });

  it('TL-03 «פרקי אבות» → пояснение и 6 פרקים (א׳–ו׳), без чипов дней; возврат «תהילים» — список פרקים #6a86f7d99a8f @prod-safe', async () => {
    await goTab('תהילים');
    await (await searchField()).waitForDisplayed({ timeout: 20000 });
    await expectVisibleText('פרקי אבות');

    // 1. Вкладка «פרקי אבות».
    await tapTextInMiddle('פרקי אבות');
    await expectTextContains('פרקי אבות נאמרים בשבתות שאחרי פסח');
    await expectTextContains('במחזור של שישה פרקים');
    for (const row of AVOT_ROWS) await expect(byTextContains(row)).toBeDisplayed({ message: `нет פרק «${row}»` });
    await expect(byText('ז׳')).not.toBeDisplayed();                 // ровно 6 פרקים
    await expect(byText('כל הימים')).not.toBeDisplayed();           // фильтр дней — только у תהילים
    await expect(byTextContains('אשרי האיש אשר')).not.toBeDisplayed();

    // 2. Назад на «תהילים» (переключатель, не заголовок и не вкладка) — список תהילים и чипы дней.
    await tapTextInMiddle('תהילים');
    await expectVisibleText('אשרי האיש אשר');
    await expectVisibleText('כל הימים');
    await expect(byTextContains('פרקי אבות נאמרים')).not.toBeDisplayed();
  });
});
